create table if not exists public.quote_requests (id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),customer_name text not null,customer_email text not null,event_date date,notes text,guest_count integer not null,package_id text not null,service_style text not null,delivery boolean not null default false,estimated_total numeric(12,2) not null);alter table public.quote_requests enable row level security;